import logging
import re
import socket
import time
from typing import Any

from taf.hw.api.hbte import PB
from taf.hw.api.hbte.base_logic import HbteException

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.base import PDU
from taf.hw.pdu.exceptions import (
    HBTEPortIsInvalid,
    HBTEReceivedPortsStatusInvalid,
    HBTESettingFailure,
    InvalidInputParameter,
    InvalidReceivedMessageFromHBTE,
)


class HBTE(PDU):

    DEFAULT_PORT = 5000

    QUERY_DEVICE = "$TA,Z*\r\n"
    QUERY_PORTS = "$TA,D*\r\n"
    SET_PORTS_CMD_FORMAT = "$TA,D,{}*\r\n"

    ON = 1
    OFF = 0

    INVALID_RECEIVED_MSG = "FF\r\n"

    def __init__(self, host: str, port: int = DEFAULT_PORT, **kwargs: Any) -> None:
        super(HBTE, self).__init__(host)
        self._port = port
        self._max_port_id = self._detect_max_port_id()

    def _detect_max_port_id(self):
        received_msg = self.execute_command(HBTE.QUERY_DEVICE)
        self._check_if_received_msg_is_valid(received_msg)

        """Query device received message: $TA,Z,HBTE-PPB-6-6-4860*"""
        if received_msg.find("DC") > 0 or received_msg.find("AC") > 0:
            return int(received_msg.split("-")[4])
        return int(received_msg.split("-")[3])

    @staticmethod
    def _check_if_received_msg_is_valid(received_msg):
        if received_msg == HBTE.INVALID_RECEIVED_MSG:
            raise InvalidReceivedMessageFromHBTE(received_msg)

    @property
    def _port_setting(self):
        return {DeviceStatus.ON: self.ON, DeviceStatus.OFF: self.OFF}

    def power_on(self, port):
        logging.debug(f"power on port {port} on HBTE")
        return self._set_port_status(int(port), DeviceStatus.ON)

    def power_off(self, port):
        logging.debug(f"power off port {port} on HBTE")
        return self._set_port_status(int(port), DeviceStatus.OFF)

    def _set_port_status(self, port, status):
        status = self._port_setting[status]
        return self._operate_ports(ports=[port], status_list=[status])

    def get_port_status(self, port):
        logging.debug(f"get port {port} status on HBTE")
        port = int(port)
        status_value = self._query_ports(ports=[port])[port]
        for status_text, value in self._port_setting.items():
            if status_value == value:
                return status_text
        return status_value

    def execute_command(self, command):
        socket_client = socket.create_connection((self._host, self._port), 3)
        time.sleep(0.5)
        logging.debug(f"send command {command} to HBTE")
        socket_client.sendall(command.encode("utf8"))
        time.sleep(0.5)
        received_msg = socket_client.recv(512).decode("utf8")
        logging.debug(f"received message {received_msg} from HBTE")
        socket_client.close()
        return received_msg

    def _operate_ports(self, ports, status_list):
        if len(ports) != len(status_list):
            raise InvalidInputParameter("The port and status number should be equal")

        self._check_if_ports_are_valid(ports)

        setting_command = self._build_setting_command(ports, status_list)
        self.execute_command(setting_command)

        time.sleep(2)
        ports_status = self._query_ports(ports)
        if dict(zip(ports, status_list)) != ports_status:
            raise HBTESettingFailure(f"ports status {ports_status}")

    def _check_if_ports_are_valid(self, ports):
        return all(map(self._is_port_id_valid, ports))

    def _is_port_id_valid(self, port_id):
        return 1 <= port_id <= self._max_port_id

    @staticmethod
    def _build_setting_command(ports, status_list):
        setting_parameters = "".join(
            ["%02x%02d" % each_port for each_port in zip(ports, status_list)]
        )
        return HBTE.SET_PORTS_CMD_FORMAT.format(setting_parameters)

    def _query_ports(self, ports):
        self._check_if_ports_are_valid(ports)
        received_msg = self.execute_command(HBTE.QUERY_PORTS)
        self._check_if_received_msg_is_valid(received_msg)
        ports_status = self._parse_ports_status(received_msg)
        return {port_id: ports_status[port_id] for port_id in ports}

    def _parse_ports_status(self, received_msg):
        """Query ports status received message: $TA,F,010102010301040005010601*\r\n"""
        ports_status = received_msg.split(",")[-1]
        ports_status = ports_status.strip().strip("*")
        ports = self._split_by_port(ports_status)
        return {int(port_status[:2]): int(port_status[2:]) for port_status in ports}

    @staticmethod
    def _split_by_port(ports_status):
        if len(ports_status) % 4:
            raise HBTEReceivedPortsStatusInvalid(ports_status)
        return re.findall(r"\d{4}", ports_status)


class HBTEPB(PDU):

    DEFAULT_PORT = 5000
    ON = "ON"
    OFF = "OFF"

    """
    The class "HBTEPB" is based on official HBTE PB api from (taf.hw.hbte.api).
    """

    def __init__(self, host, port=None, **kwargs):
        self._host = host
        super(HBTEPB, self).__init__(self._host)

        self._port = port or self.DEFAULT_PORT
        self._pb = PB(self._host, self._port)

    def _set_port_status(self, port, status):
        logging.debug(f"set port {port} status {status}")
        try:
            if status == DeviceStatus.OFF:
                return self._pb.closePort(channel=[port])
            return self._pb.openPort(channel=[port])
        except HbteException as err:
            raise HBTEPortIsInvalid(f"HBTE {port} port incorrect, err={err}")

    def get_port_status(self, port):
        """Get PDU port status"""
        try:
            status = self._pb.queryPort(channel=[port])[port]
        except HbteException as err:
            raise HBTEPortIsInvalid(f"HBTE {port} port incorrect, err={err}")

        if status == self.OFF:
            return DeviceStatus.OFF
        return DeviceStatus.ON

    @property
    def _port_setting(self):
        return {DeviceStatus.ON: self.ON, DeviceStatus.OFF: self.OFF}


class HBTEPPB184820(HBTEPB):
    pass
